package security

const GoGetterModule = "github.com/hashicorp/go-getter"
const GoGetterMinimumVersion = "v1.8.6"
const GoGetterAdvisory = "HCSEC-2024-09"
package fetcher

import (
	"encoding/json"
	"os"
)

type Source struct {
	Name string `json:"name"`
	URL  string `json:"url"`
}

type Settings struct {
	StagingDir string   `json:"staging_dir"`
	Sources    []Source `json:"sources"`
}

func LoadSettings(path string) (Settings, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Settings{}, err
	}
	var settings Settings
	if err := json.Unmarshal(data, &settings); err != nil {
		return Settings{}, err
	}
	return settings, nil
}
package fetcher

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	getter "github.com/hashicorp/go-getter"
)

type BundleManifest struct {
	Bundle  string `json:"bundle"`
	Version string `json:"version"`
	SHA256  string `json:"sha256"`
}

type Summary struct {
	Fetched int              `json:"fetched"`
	Bundles []BundleManifest `json:"bundles"`
}

func Run(settings Settings) (Summary, error) {
	if settings.StagingDir == "" {
		return Summary{}, fmt.Errorf("staging_dir is required")
	}
	summary := Summary{Bundles: []BundleManifest{}}
	for _, source := range settings.Sources {
		if source.Name == "" || source.URL == "" {
			return Summary{}, fmt.Errorf("source name and url are required")
		}
		target := filepath.Join(settings.StagingDir, source.Name)
		if err := getter.Get(target, source.URL); err != nil {
			return Summary{}, fmt.Errorf("fetch %s: %w", source.Name, err)
		}
		manifest, err := readManifest(filepath.Join(target, "manifest.json"))
		if err != nil {
			return Summary{}, fmt.Errorf("read manifest for %s: %w", source.Name, err)
		}
		summary.Fetched++
		summary.Bundles = append(summary.Bundles, manifest)
	}
	return summary, nil
}

func readManifest(path string) (BundleManifest, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return BundleManifest{}, err
	}
	var manifest BundleManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return BundleManifest{}, err
	}
	return manifest, nil
}
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	"git.meridian.internal/release/artifact-fetcher/internal/fetcher"
)

func main() {
	configPath := flag.String("config", "configs/sources.json", "source catalog path")
	flag.Parse()

	settings, err := fetcher.LoadSettings(*configPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	summary, err := fetcher.Run(settings)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	encoded, err := json.Marshal(summary)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Println(string(encoded))
}

